// GUARDRAIL 1: Verification Challenge (GET) + payload validation (POST)
const body = $input.all()[0].json;
const qs = body.query || {};
// Responde ao challenge de verificação do Meta
if (qs['hub.mode'] === 'subscribe') {
  const tok = ($env['WEBHOOK_VERIFY_TOKEN'] || '');
  if (qs['hub.verify_token'] === tok)
    return [{ json: { type: 'CHALLENGE', challenge: qs['hub.challenge'] } }];
  return [{ json: { type: 'INVALID', reason: 'bad_token' } }];
}
// Valida payload POST
const msgs = body?.entry?.[0]?.changes?.[0]?.value?.messages;
if (!msgs || !msgs.length) return [{ json: { type: 'INVALID', reason: 'no_messages' } }];
return [{ json: { type: 'VALID', body } }];

// Extrai dados + GUARDRAIL 2 (replay attack) + GUARDRAIL 3 (tamanho máximo)
const body = $input.all()[0].json.body;
const message = body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const contact = body?.entry?.[0]?.changes?.[0]?.value?.contacts?.[0];
const phoneNumber = message?.from;
if (!phoneNumber) throw new Error('Mensagem sem telefone.');
// Replay attack: descartar mensagens com mais de 5 minutos
const msgTime = parseInt(message?.timestamp || '0', 10) * 1000;
if ((Date.now() - msgTime) > 300000)
  return [{ json: { skip: true, phoneNumber, reason: 'too_old' } }];
const messageType = message?.type;
if (messageType === 'sticker')
  return [{ json: { skip: true, phoneNumber, reason: 'sticker_ignored' } }];
let messageContent = '', mediaId = '';
if (messageType === 'text')
  messageContent = (message?.text?.body || '').substring(0, 4000); // trunca
else if (messageType === 'audio')  mediaId = message?.audio?.id    || '';
else if (messageType === 'image')  { mediaId = message?.image?.id  || ''; messageContent = message?.image?.caption    || ''; }
else if (messageType === 'document'){ mediaId = message?.document?.id || ''; messageContent = message?.document?.caption || ''; }
return [{ json: {
  phoneNumber, contactName: contact?.profile?.name || 'Cliente',
  messageId: message?.id, timestamp: message?.timestamp,
  messageType, messageContent, mediaId,
  processedAt: new Date().toISOString(), platform: 'whatsapp-dra-julia', skip: false
} }];

// Combina resultados multimodais e classifica área jurídica.
// CORREÇÃO: remove a conexão circular de volta ao ChatGPT Principal.
const orig = $('Processar Mensagem Jurídica').item.json;
let texto = '', analise = '', audio = '', erroMidia = '';
try { const a = $('Transcrever Áudio (Whisper)').all(); if (a?.length) { audio = a[0].json?.text || ''; texto = audio; } } catch(_){}
try { const d = $('Analisar Documento (GPT-4o Vision)').all(); if (d?.length) { analise = d[0].json?.choices?.[0]?.message?.content || ''; texto = analise; } } catch(_){}
if (!texto && orig.messageType === 'text') texto = orig.messageContent;
if (!texto && orig.mediaId) erroMidia = 'Não foi possível processar o arquivo. Tente reenviar ou descreva o caso por texto.';
// Classificação por área jurídica com banco de palavras-chave expandido
const c = texto.toLowerCase();
const mapa = [
  ['Direito Trabalhista',    ['clt','rescisão','demissão','salário','fgts','horas extras','trabalhista','emprego']],
  ['Direito de Família',     ['divórcio','guarda','pensão alimentícia','inventário','herança','casamento','partilha']],
  ['Direito Imobiliário',    ['imóvel','escritura','locação','aluguel','usucapião','compra e venda','registro']],
  ['Direito Criminal',       ['crime','prisão','delegacia','boletim de ocorrência','furto','roubo','inquérito']],
  ['Direito Tributário',     ['imposto','tributo','receita federal','irpf','simples nacional','icms','iss']],
  ['Direito do Consumidor',  ['consumidor','procon','garantia','produto defeituoso','cdc','devolução']],
  ['Direito Empresarial',    ['empresa','cnpj','sociedade','mei','contrato social','compliance','ltda']],
  ['Direito Processual',     ['processo','tribunal','sentença','petição','recurso','audiência']],
  ['Direito Administrativo', ['concurso público','servidor','licitação','órgão público','ato administrativo']]
];
let area = 'Geral';
for (const [a, words] of mapa) { if (words.some(w => c.includes(w))) { area = a; break; } }
return [{ json: { ...orig, textoProcessado: texto, analiseDocumento: analise, audioTranscrito: audio, areaJuridica: area, erroMidia, temAnalise: !!(analise || audio) } }];

// Detecta comandos especiais da resposta do GPT e roteia.
const resp = $input.all()[0].json?.choices?.[0]?.message?.content || '';
const orig = $('Combinar Resultados Jurídicos').item.json;
// Fallback para erro do GPT
if (!resp) return [{ json: { ...orig, acaoTipo: 'RESPOSTA_DIRETA', respostaFinal: 'Desculpe, estou com dificuldades técnicas. Tente novamente em instantes. ⚖️' } }];
// GERAR_DOCUMENTO
if (resp.includes('GERAR_DOCUMENTO')) {
  const m = resp.match(/GERAR_DOCUMENTO\|([^|]+)\|([\s\S]+)/);
  if (m) return [{ json: { ...orig, acaoTipo: 'GERAR_DOCUMENTO', documento: {
    tipo: m[1].trim(), detalhes: m[2].trim().substring(0,2000),
    solicitadoEm: new Date().toISOString(), status: 'Em elaboração',
    cliente: orig.contactName, telefone: orig.phoneNumber
  }, respostaFinal: resp } }];
}
// AGENDAR_CONSULTA
if (resp.includes('AGENDAR_CONSULTA')) {
  const m = resp.match(/AGENDAR_CONSULTA\|([^|]+)\|([^|]+)\|([^|]+)\|([\s\S]+)/);
  if (m) {
    const dt = new Date(); dt.setDate(dt.getDate()+1);
    if (dt.getDay()===0) dt.setDate(dt.getDate()+1); // domingo → segunda
    if (dt.getDay()===6) dt.setDate(dt.getDate()+2); // sábado → segunda
    dt.setHours(14,0,0,0);
    const fim = new Date(dt.getTime()+3600000);
    return [{ json: { ...orig, acaoTipo: 'AGENDAR_CONSULTA', consulta: {
      nome: m[1].trim(), telefone: m[2].trim(), area: m[3].trim(),
      dataPreferida: m[4].trim().substring(0,100),
      dataAgendada: dt.toISOString(), dataFim: fim.toISOString(),
      titulo: `Consulta Jurídica – ${m[1].trim()} (${m[3].trim()})`,
      descricao: `Agendada via WhatsApp\nCliente: ${m[1].trim()}\nTelefone: ${m[2].trim()}\nÁrea: ${m[3].trim()}\nStatus: Agendada`,
      status: 'Agendada'
    }, respostaFinal: resp } }];
  }
}
// CRIAR_CLIENTE
if (resp.includes('CRIAR_CLIENTE')) {
  const m = resp.match(/CRIAR_CLIENTE\|([^|]+)\|([^|]+)\|([^|]*)\|([^\n]*)/);
  if (m) return [{ json: { ...orig, acaoTipo: 'CRIAR_CLIENTE', novoCliente: {
    nome: m[1].trim(), telefone: m[2].trim() || orig.phoneNumber,
    email: m[3].trim() || null, cpf: m[4].trim() || null
  }, respostaFinal: resp } }];
}
// CONSULTAR_ANDAMENTO
if (resp.includes('CONSULTAR_ANDAMENTO')) {
  const m = resp.match(/CONSULTAR_ANDAMENTO\|?([^\n]*)/);
  const telefoneConsulta = (m && m[1].trim()) ? m[1].trim() : orig.phoneNumber;
  return [{ json: { ...orig, acaoTipo: 'CONSULTAR_ANDAMENTO', telefoneConsulta, respostaFinal: resp } }];
}
return [{ json: { ...orig, acaoTipo: 'RESPOSTA_DIRETA', respostaFinal: resp } }];

const txt = $input.all()[0].json?.choices?.[0]?.message?.content || 'Não foi possível gerar o documento. Entre em contato com o escritório.';
const d = $('Interpretar Resposta e Detectar Ação').item.json;
return [{ json: { ...d, documentoGerado: txt, respostaFinal: txt } }];

// Sanitiza resposta: remove pipes do protocolo interno para não vazar no WhatsApp.
const item = $input.all()[0]?.json || {};
const txt = (item.respostaFinal || item.choices?.[0]?.message?.content || 'Olá! Sou a Dra. Júlia, sua advogada virtual. Como posso ajudá-lo(a)? ⚖️👩‍💼')
  .replace(/GERAR_DOCUMENTO\|[^\n]*/g, '')
  .replace(/AGENDAR_CONSULTA\|[^\n]*/g, '')
  .replace(/CRIAR_CLIENTE\|[^\n]*/g, '')
  .replace(/CONSULTAR_ANDAMENTO\|?[^\n]*/g, '')
  .trim();
const phone = item.phoneNumber || $('Processar Mensagem Jurídica').item.json.phoneNumber;
return [{ json: { textoFinal: txt, phoneNumber: phone } }];

// Filtra consultas do dia com validação robusta de número de telefone.
const hoje = new Date(); hoje.setHours(0,0,0,0);
const items = $input.all();
const result = [];
for (const i of items) {
  const ev = i.json;
  if (!ev?.start) continue;
  const dt = new Date(ev.start.dateTime || ev.start.date); dt.setHours(0,0,0,0);
  if (dt.getTime() !== hoje.getTime()) continue;
  const desc = ev.description || '';
  const m = desc.match(/Telefone:\s*([+\d\s\-\(\)]{8,20})/);
  if (!m) continue;
  const tel = m[1].replace(/[\s\-\(\)]/g,'');
  // Validação E.164 / número BR
  if (!/^\+?[1-9]\d{7,14}$/.test(tel)) continue;
  result.push({ json: { titulo: ev.summary || 'Consulta', inicio: ev.start.dateTime || ev.start.date, telefone: tel } });
}
if (!result.length) return [{ json: { noConsultas: true } }];
return result;

