// Monta a resposta final apos tentar criar o cliente no ManuADV
const orig = $('Ação: Criar Cliente?').item.json;
const http = $input.all()[0].json;
const ok = !http.error && !http.errorMessage;
const nome = orig.novoCliente?.nome || 'você';
const texto = ok
  ? `Pronto! Cadastrei ${nome} como cliente(a). Em breve alguém do escritório entra em contato para dar continuidade. ⚖️`
  : `Consegui entender seus dados, mas tive um problema técnico ao cadastrar no sistema agora. Vou avisar a equipe para cadastrar manualmente.`;
return [{ json: { ...orig, respostaFinal: texto } }];

// Formata o status do processo encontrado no ManuADV para o WhatsApp
const orig = $('Ação: Consultar Andamento?').item.json;
const http = $input.all()[0].json;
let texto;
if (http.error || http.errorMessage) {
  texto = 'Não consegui consultar o andamento agora, tente novamente em instantes ou aguarde o contato do escritório.';
} else {
  const cases = Array.isArray(http) ? http : (http.cases || http.data || []);
  if (!cases || cases.length === 0) {
    texto = 'Não encontrei nenhum processo vinculado a este número. Se você já é cliente, confirme o telefone cadastrado com o escritório.';
  } else {
    texto = cases.map(c => `📁 ${c.title || c.numero || 'Processo'}\nStatus: ${c.status}\nÚltima atualização: ${c.updatedAt || 'não informado'}`).join('\n\n');
    texto += '\n\n⚠️ Esta informação tem caráter orientativo, qualquer dúvida fale com seu advogado.';
  }
}
return [{ json: { ...orig, respostaFinal: texto } }];

// Espera body: { telefone, mensagem, tipo, clienteNome }
const body = $input.all()[0].json.body || {};
if (!body.telefone) throw new Error('Notificação sem telefone.');
const texto = body.mensagem || `Olá${body.clienteNome ? ', ' + body.clienteNome : ''}! Temos uma atualização no seu caso.`;
return [{ json: { phoneNumber: body.telefone, textoFinal: texto.substring(0, 4000) } }];
